// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation.fragment;

/**
 * Batch (slice) execution forms for predicate fragments (fragment-fusion M2). The canonical shape: one pass classifies
 * and compacts fast-path survivors into {@code outputSel} and undecidable ids into {@code escapeSel}; the escape batch
 * is evaluated separately against the bound exact fallback (amortizing scratch-row traffic and keeping the hot loop
 * branch-predictable); exact survivors merge back in encounter order. One virtual dispatch per slice, monomorphic
 * primitive loop inside — never one dispatch per row.
 *
 * <p>
 * "Batched" is not "vectorized": these loops amortize dispatch and isolate profiles; SIMD-friendliness is a separate
 * physical-variant question measured before it is claimed.
 */
public final class FragmentSlices {

	private FragmentSlices() {
	}

	/** Packs a slice result: accepted fast-path survivors in the low half, escaped candidates in the high half. */
	public static long result(int acceptedCount, int escapedCount) {
		return ((long) escapedCount << 32) | (acceptedCount & 0xffff_ffffL);
	}

	public static int acceptedCount(long result) {
		return (int) result;
	}

	public static int escapedCount(long result) {
		return (int) (result >>> 32);
	}

	/**
	 * Predicate slice over one column. {@code inputSel[0..inputCount)} are row ordinals (ascending encounter order);
	 * ids are read at {@code column[base + ordinal]}. Fast-path TRUE ordinals compact into {@code outputSel},
	 * undecidable ordinals into {@code escapeSel}; FALSE/ERROR ordinals are dropped. Returns
	 * {@link FragmentSlices#result}.
	 */
	public interface UnaryPredicateSlice {
		long select1(long[] column, int base, int[] inputSel, int inputCount, int[] outputSel, int[] escapeSel,
				FragmentBinding binding);
	}

	/** Predicate slice over two aligned columns; contract identical to {@link UnaryPredicateSlice}. */
	public interface BinaryPredicateSlice {
		long select2(long[] columnA, long[] columnB, int base, int[] inputSel, int inputCount, int[] outputSel,
				int[] escapeSel, FragmentBinding binding);
	}

	/** The default escape-partition slice over any compiled unary predicate. */
	public static UnaryPredicateSlice unary(LongPredicateFragment fragment) {
		return (column, base, inputSel, inputCount, outputSel, escapeSel, binding) -> {
			int accepted = 0;
			int escaped = 0;
			for (int i = 0; i < inputCount; i++) {
				int ordinal = inputSel[i];
				PredicateStatus status = fragment.test(column[base + ordinal], -1L, -1L, binding);
				if (status == PredicateStatus.TRUE) {
					outputSel[accepted++] = ordinal;
				} else if (status == PredicateStatus.ESCAPE) {
					escapeSel[escaped++] = ordinal;
				}
			}
			FragmentTelemetry.FAST_PATH_DECISIONS.add(inputCount - escaped);
			FragmentTelemetry.ESCAPES.add(escaped);
			return result(accepted, escaped);
		};
	}

	/** The default escape-partition slice over any compiled binary predicate. */
	public static BinaryPredicateSlice binary(LongPredicateFragment fragment) {
		return (columnA, columnB, base, inputSel, inputCount, outputSel, escapeSel, binding) -> {
			int accepted = 0;
			int escaped = 0;
			for (int i = 0; i < inputCount; i++) {
				int ordinal = inputSel[i];
				PredicateStatus status = fragment.test(columnA[base + ordinal], columnB[base + ordinal], -1L, binding);
				if (status == PredicateStatus.TRUE) {
					outputSel[accepted++] = ordinal;
				} else if (status == PredicateStatus.ESCAPE) {
					escapeSel[escaped++] = ordinal;
				}
			}
			FragmentTelemetry.FAST_PATH_DECISIONS.add(inputCount - escaped);
			FragmentTelemetry.ESCAPES.add(escaped);
			return result(accepted, escaped);
		};
	}

	/**
	 * Resolves an escape partition through the exact fallback and merges survivors with the fast-path survivors,
	 * restoring encounter order (both partitions are ascending because {@code inputSel} was). {@code merged} must have
	 * room for {@code acceptedCount + escapedCount} ordinals; returns the merged survivor count.
	 */
	public static int resolveEscapes(long[] column, int base, int[] outputSel, int acceptedCount, int[] escapeSel,
			int escapedCount, FragmentBinding binding, int[] merged) {
		int survivors = 0;
		for (int i = 0; i < escapedCount; i++) {
			int ordinal = escapeSel[i];
			if (binding.escapeToExact(column[base + ordinal], -1L, -1L)) {
				escapeSel[survivors++] = ordinal;
			}
		}
		return mergeAscending(outputSel, acceptedCount, escapeSel, survivors, merged);
	}

	/** Merges two ascending ordinal runs into {@code merged}; returns the total count. */
	public static int mergeAscending(int[] left, int leftCount, int[] right, int rightCount, int[] merged) {
		int l = 0;
		int r = 0;
		int out = 0;
		while (l < leftCount && r < rightCount) {
			merged[out++] = left[l] <= right[r] ? left[l++] : right[r++];
		}
		while (l < leftCount) {
			merged[out++] = left[l++];
		}
		while (r < rightCount) {
			merged[out++] = right[r++];
		}
		return out;
	}
}
